// Corretor de bolso: faz o papel do Jest aqui no compilador on-line.
// Deixe estas linhas como estão e escreva o seu código depois delas.
function test(nome, funcao) {
  try {
    funcao();
    console.log(`√ ${nome}`);
  } catch (erro) {
    console.log(`× ${nome}`);
    console.log(`  ${erro.message}`);
  }
}
test.each = (casos) => (nome, funcao) => {
  for (const caso of casos) {
    let i = 0;
    const titulo = nome.replace(/%[dijs]/g, (marca) => {
      const valor = caso[i++];
      return marca === '%j' ? JSON.stringify(valor) : String(valor);
    });
    test(titulo, () => funcao(...caso));
  }
};
function expect(recebido) {
  const texto = (valor) => JSON.stringify(valor);
  return {
    toBe(esperado) {
      if (recebido !== esperado) throw new Error(`Expected: ${texto(esperado)} | Received: ${texto(recebido)}`);
    },
    toEqual(esperado) {
      if (texto(recebido) !== texto(esperado)) throw new Error(`Expected: ${texto(esperado)} | Received: ${texto(recebido)}`);
    },
  };
}
